#!/usr/bin/env node
/**
 * Turns the stored TMC files into the artifacts the application bundles.
 *
 *   node scripts/generate-tmc-data.mjs           # write src/data/tmc/**
 *   node scripts/generate-tmc-data.mjs --check   # verify only, write nothing
 *
 * Generation happens here rather than in the browser, and the results are committed,
 * so that a driver update arrives as a reviewable diff instead of as behaviour that
 * changes the next time the page is loaded.
 *
 * Nothing here is timestamped. A generated file must change only when its input
 * changed, otherwise every run produces a commit and the diff stops meaning anything.
 */

import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { compareVersions } from './lib/feed.mjs'
import { buildMeta, buildModuleDescriptors } from './lib/meta.mjs'
import { MC_OVERLAY, SD_OVERLAY } from './lib/overlay.mjs'
import { artifactVersion, hasTmc, readManifest, readTmc, resolveTmcSource } from './lib/store.mjs'
import { parseTmc } from './lib/tmc.mjs'
import { renderXtiTemplate } from './lib/xti.mjs'

const OUTPUT_DIR = 'src/data/tmc'

/**
 * The TwinCAT XAE build recorded in the generated file's root element.
 *
 * It describes the engineering environment that would have written the file, not the
 * driver, so it cannot come from the TMC. It only appears in the `TcVersion` attribute
 * and does not affect how TwinCAT reads the parameter set.
 */
const TWINCAT_VERSION = '3.1.4026.20'

function generateVersion(root, entry, softDriveSource) {
  const source = artifactVersion(entry)
  const mc = parseTmc(readTmc(root, source, 'TcIoXts.tmc'))

  // Not every TcIoXts release ships a SoftDrive TMC. The SoftDrive side describes the
  // format being migrated away from, and an imported SoftDrive file states no version,
  // so the newest description available is the right one to read it with.
  const sdVersion = hasTmc(root, source, 'TcSoftDrive.tmc') ? source : softDriveSource
  const sd = parseTmc(readTmc(root, sdVersion, 'TcSoftDrive.tmc'))

  const mcMeta = buildMeta(mc, MC_OVERLAY)
  const sdMeta = buildMeta(sd, SD_OVERLAY)
  const errors = [...mcMeta.errors, ...sdMeta.errors]

  if (errors.length > 0) {
    return { version: mc.library.version, errors, warnings: [...mcMeta.warnings, ...sdMeta.warnings] }
  }

  const models = { mc, sd }

  return {
    version: mc.library.version,
    errors: [],
    warnings: [...mcMeta.warnings, ...sdMeta.warnings],
    dataset: {
      version: mc.library.version,
      libraries: { TcIoXts: mc.library.version, TcSoftDrive: sd.library.version },
      mc: { modules: buildModuleDescriptors(models, 'mc', MC_OVERLAY), parameters: mcMeta.meta },
      sd: { modules: buildModuleDescriptors(models, 'sd', SD_OVERLAY), parameters: sdMeta.meta },
    },
    template: renderXtiTemplate(mc, { twinCatVersion: TWINCAT_VERSION }),
  }
}

/**
 * The default version's artifacts are imported statically, so the path has to be a
 * literal. Emitting that import as a generated module keeps the registry from naming a
 * version it would then have to be edited to change.
 */
function renderDefaultModule(version, entry) {
  const directory = artifactVersion(entry)

  return `// Generated by scripts/generate-tmc-data.mjs — do not edit.
//
// The default driver version is imported eagerly: several call sites read parameter
// metadata while their module is initialising, and most sessions never switch away
// from it. Every other version is a lazily-loaded chunk, see ../../lib/tmc/registry.ts.
import dataset from './${directory}/dataset.json'
import template from './${directory}/template.xti?raw'

/** TcIoXts ${version}. */
export const DEFAULT_DATASET = dataset
export const DEFAULT_TEMPLATE = template
`
}

function main() {
  const check = process.argv.includes('--check')
  const root = fileURLToPath(new URL('..', import.meta.url))
  const manifest = readManifest(root)

  const usable = manifest.versions.filter((entry) => entry.status === 'ok')
  if (usable.length === 0) {
    throw new Error(`${'tmc/index.json'} lists no usable version. Run 'npm run tmc:sync' first.`)
  }

  // The user picks a driver version, not a package version, and several packages can
  // ship the same driver. The newest package wins where they collide.
  const byDriverVersion = new Map()
  for (const entry of [...usable].sort((a, b) => compareVersions(a.package, b.package))) {
    byDriverVersion.set(entry.tcIoXts, entry)
  }

  const softDriveSource = resolveTmcSource(root, manifest, 'TcSoftDrive.tmc')
  if (!softDriveSource) {
    throw new Error('No stored version carries TcSoftDrive.tmc, so the SoftDrive side cannot be described.')
  }

  const results = []
  const failures = []

  for (const [driverVersion, entry] of byDriverVersion) {
    const result = generateVersion(root, entry, softDriveSource)

    if (result.errors.length > 0) {
      failures.push({ driverVersion, errors: result.errors })
      continue
    }

    results.push({ driverVersion, entry, ...result })
    for (const warning of result.warnings) console.warn(`  ${driverVersion}: ${warning}`)
  }

  const ordered = results.sort((a, b) => compareVersions(b.driverVersion, a.driverVersion))

  const index = {
    // Newest first, which is also the order the version picker renders.
    defaultVersion: ordered[0]?.driverVersion,
    versions: ordered.map(({ driverVersion, entry, warnings, dataset }) => ({
      version: driverVersion,
      package: entry.package,
      artifacts: artifactVersion(entry),
      published: entry.published ?? null,
      // The SoftDrive metadata this version is described with, which is its own only
      // when the release shipped one.
      tcSoftDrive: dataset.libraries.TcSoftDrive,
      unlistedParameters: warnings.length,
    })),
  }

  if (failures.length > 0) {
    console.error('\nThese driver versions cannot be supported without an overlay change:\n')
    for (const failure of failures) {
      console.error(`  ${failure.driverVersion}`)
      for (const error of failure.errors) console.error(`    - ${error}`)
    }
  }

  if (check) {
    const outputDir = join(root, OUTPUT_DIR)
    const written = new Set(readdirSync(outputDir, { withFileTypes: true }).filter((e) => e.isDirectory()).map((e) => e.name))
    const expected = new Set(ordered.map((result) => artifactVersion(result.entry)))
    const stale = [...written].filter((name) => !expected.has(name))
    const missing = [...expected].filter((name) => !written.has(name))

    if (stale.length > 0 || missing.length > 0) {
      throw new Error(`src/data/tmc is out of date (stale: ${stale.join(', ') || 'none'}, missing: ${missing.join(', ') || 'none'}).`)
    }

    const expectedDefault = renderDefaultModule(index.defaultVersion, ordered[0].entry)
    if (readFileSync(join(outputDir, 'default.ts'), 'utf8') !== expectedDefault) {
      throw new Error(`src/data/tmc/default.ts does not point at ${index.defaultVersion}.`)
    }

    console.log(`Checked ${ordered.length} driver version(s).`)
    if (failures.length > 0) process.exitCode = 1
    return
  }

  if (failures.length > 0) {
    throw new Error('Refusing to write artifacts while a driver version fails its overlay check.')
  }

  const outputDir = join(root, OUTPUT_DIR)
  rmSync(outputDir, { recursive: true, force: true })
  mkdirSync(outputDir, { recursive: true })

  for (const result of ordered) {
    const directory = join(outputDir, artifactVersion(result.entry))
    mkdirSync(directory, { recursive: true })
    writeFileSync(join(directory, 'dataset.json'), `${JSON.stringify(result.dataset, null, 2)}\n`)
    writeFileSync(join(directory, 'template.xti'), result.template)
  }

  writeFileSync(join(outputDir, 'index.json'), `${JSON.stringify(index, null, 2)}\n`)
  writeFileSync(join(outputDir, 'default.ts'), renderDefaultModule(index.defaultVersion, ordered[0].entry))

  console.log(`Wrote ${ordered.length} driver version(s) to ${OUTPUT_DIR}, default ${index.defaultVersion}.`)
}

try {
  main()
} catch (error) {
  console.error(error.message)
  process.exit(1)
}
